def comps(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if not seen[i][j] and g[i][j]:
                c=g[i][j]; st=[(i,j)]; seen[i][j]=True; cells=[]
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and not seen[x][y] and g[x][y]==c:
                            seen[x][y]=True; st.append((x,y))
                out.append((list(cells),c))
    return out

def f(g):
    H,W=len(g),len(g[0])
    cs=comps(g)
    groups={}
    for cells,c in cs:
        r=min(p[0] for p in cells)
        groups.setdefault(groups.get(None,None) if False else None,[]).append((cells,c,r))
    # simple grouping: consecutive rows
    items=sorted(cs,key=lambda sc:min(p[0] for p in sc[0]))
    groups=[]
    cur=None
    for cells,c in items:
        r=min(p[0] for p in cells)
        if cur is None or r!=cur[-1][2]+1:
            groups.append([])
        groups[-1].append((cells,c))
        cur=groups[-1]
    o=[[0]*W for _ in range(H)]
    for grp in groups:
        tot=sum(max(p[1] for p in cl)-min(p[0] for p in cl) for cl,_ in grp)
        # careful: width should be bbox width
        tot=sum((max(p[1] for p in cl)-min(p[1] for p in cl)+1) for cl,_ in grp)
        base=W-tot
        cum=0
        for cells,c in grp:
            lw=max(p[1] for p in cells)-min(p[1] for p in cells)+1
            for a,b in cells:
                o[a][b+cum]=c
            cum+=lw
    return o

