def f(g):
    cs=list(comps(g)); H,W=len(g),len(g[0])
    groups=[]; cur=[cs[0]]
    for c in cs[1:]:
        # overlapping row intervals -> same group
        prev=max(cur,key=lambda x:(max(y for y,_ in x)-min(y for y,_ in x)))
        if not any(max(y for y,_ in x)>=min(y for y,_ in c) and max(y for y,_ in x)<=max(y for y,_ in c) for x in cur):
            pass
        # simpler: group if row span intersects any member
        if any((max(yy for yy,_ in x2) >= min(yy for yy,_ in c)) and (min(yy for yy,_ in x2) <= max(yy for yy,_ in c)) for x2 in cur):
            cur.append(c)
        else:
