    S=shapes_of(g)
    sp=set()
    for _,cp in S: sp.update(cp)
    res=[r[:] for r in g]
    for c,cp in S:
        if len(cp)>=2: continue
        for y,x in cp:
            best=None
            for y2,x2 in sp:
                if metric=='manhattan': d=max(abs(y-y2),abs(x-x2))   # Chebyshev-ish test
